from pathlib import Path
import sys, tempfile, subprocess, json, hashlib, datetime, shutil
ROOT=Path.cwd(); OUT=ROOT/'.playbook-artifacts/delivery-acceptance-20261009/review'; OUT.mkdir(parents=True,exist_ok=True)
FILES=['distribution/desktop/setup_core.py','distribution/desktop/desktop_setup.py','distribution/desktop/desktop_runtime.py','distribution/desktop/build.py','distribution/desktop/test_setup.py','tools/playbook_environment.py','tools/solution_record.py','plugins/playbook-native/skills/playbook/SKILL.md','plugins/playbook-native/skills/playbook/references/review.md','plugins/playbook-native/skills/playbook/references/setup.md','plugins/playbook-native/skills/playbook/references/environment.md','plugins/playbook-native/skills/playbook/references/lifecycle/discover.md','plugins/playbook-native/skills/playbook/references/lifecycle/verify.md','distribution/native/build.py','distribution/native/sync_runtime.py','.github/workflows/native-checks.yml']
