def run(name,args):
 start=datetime.datetime.now(datetime.timezone.utc).isoformat(); r=subprocess.run(args,cwd=ROOT,capture_output=True,text=True,encoding='utf-8',timeout=180)
 (OUT/(name+'.stdout.txt')).write_text(r.stdout,encoding='utf-8'); (OUT/(name+'.stderr.txt')).write_text(r.stderr,encoding='utf-8')
 commands.append({'name':name,'argv':args,'exit_code':r.returncode,'start_utc':start,'end_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}); return r
