 setup_core.apply(setup_core.plan(root,kit,'install',['playbook-helper']),consent=True); moved=p/'moved'; shutil.copytree(root,moved)
 cases={'copied_before':setup_core.installation_status(moved)}
 cases['copied_update']=setup_core.apply(setup_core.plan(moved,kit,'update',['playbook-helper']),consent=True); cases['copied_after_update']=setup_core.installation_status(moved)
 (moved/setup_core.JOURNAL).unlink(); cases['missing_journal_before']=setup_core.installation_status(moved)
 cases['missing_journal_remove']=setup_core.apply(setup_core.plan(moved,kit,'remove'),consent=True); cases['owner_data_after']=(moved/'notes.txt').read_text()
